```sql
CREATE PROCEDURE dbo.TransferMoney
    @FromAccount INT,
    @ToAccount   INT,
    @Amount      DECIMAL(18,2)
AS
BEGIN
    SET NOCOUNT ON;

    -- 1. basic validation
    IF @FromAccount = @ToAccount
    BEGIN
        RAISERROR('Source and destination must differ.', 16, 1);
        RETURN;
    END

    IF @Amount <= 0
    BEGIN
        RAISERROR('Amount must be positive.', 16, 1);
        RETURN;
    END

    -- 2. start transaction
    BEGIN TRY
        BEGIN TRANSACTION;

        -- 3. YOUR PART: debit @FromAccount and credit @ToAccount,
        --    checking that each UPDATE affects exactly one row.
        /* write the two UPDATE statements here */

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 ROLLBACK TRANSACTION;
        RAISERROR(ERROR_MESSAGE(), 16, 1);
    END CATCH;
END
GO
```

